	private static Throwable cancelWhileEntered(Callable<?> action, NativeCancellationToken owner,
			CountDownLatch entered,
			CountDownLatch release) throws Exception {
		return cancelWhileEntered(action, owner, entered, release, KernelQueryCancelledException.class);
	}

	private static Throwable cancelWhileEntered(Callable<?> action, NativeCancellationToken owner,
			CountDownLatch entered,
			CountDownLatch release, Class<? extends Throwable> expected) throws Exception {
		var executor = Executors.newSingleThreadExecutor();
		var worker = executor.submit(() -> {
			try (var scope = owner.enter()) {
				return action.call();
			}
		});
		try {
			assertThat(entered.await(5, TimeUnit.SECONDS)).isTrue();
			owner.requestCancellation();
			release.countDown();
			ExecutionException failure = assertThrows(ExecutionException.class, () -> worker.get(5, TimeUnit.SECONDS));
			assertThat(failure.getCause()).isInstanceOf(expected);
			return failure.getCause();
		} finally {
			release.countDown();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}
	}

